//! Requests: the entity (it mirrors the migration), its relations and its label. Validation is in
//! params.rs, the queries in queries.rs; both are re-exported here (`request::find`, `request::RequestParams`).
//! Generated by `cargo offrails generate resource requests agent:references{agent} title:string description:text category:string location:string budget:money`.
//! APP: say what a request is, and cite its spec (product/features/requests.md).

use sea_orm::entity::prelude::*;

mod browse;
mod lifecycle;
mod params;
mod queries;

pub use browse::*;
pub use lifecycle::*;
pub use params::*;
pub use queries::*;

#[derive(Clone, Debug, PartialEq, Eq, DeriveEntityModel)]
#[sea_orm(table_name = "requests")]
pub struct Model {
    #[sea_orm(primary_key)]
    pub id: i64,
    /// The owner, set from the session (never from params).
    pub user_id: i64,
    pub agent_id: i64,
    pub title: String,
    #[sea_orm(column_type = "Text")]
    pub description: String,
    pub category: String,
    pub location: String,
    /// Integer cents: never a float.
    pub budget_cents: i64,
    pub status: RequestStatus,
    pub created_at: DateTimeUtc,
    pub updated_at: DateTimeUtc,
    // samples: columns
}

#[derive(Copy, Clone, Debug, EnumIter, DeriveRelation)]
pub enum Relation {
    #[sea_orm(
        belongs_to = "super::user::Entity",
        from = "Column::UserId",
        to = "super::user::Column::Id",
        on_delete = "Cascade"
    )]
    Owner,
    #[sea_orm(
        belongs_to = "super::agent::Entity",
        from = "Column::AgentId",
        to = "super::agent::Column::Id",
        on_delete = "Restrict"
    )]
    Agent,
    // application
    #[sea_orm(has_many = "super::application::Entity")]
    Applications,
    // samples: relations
}

impl Related<super::user::Entity> for Entity {
    fn to() -> RelationDef {
        Relation::Owner.def()
    }
}

impl Related<super::agent::Entity> for Entity {
    fn to() -> RelationDef {
        Relation::Agent.def()
    }
}

// application
impl Related<super::application::Entity> for Entity {
    fn to() -> RelationDef {
        Relation::Applications.def()
    }
}

// samples: related

/// Must stay empty: callbacks are banned (.offrails/guides/models.md#side-effects-no-callbacks).
impl ActiveModelBehavior for ActiveModel {}

impl Model {
    /// How a request is named in lists and `<select>`s.
    pub fn label(&self) -> String {
        self.title.clone()
    }
}

/// Lifecycle is controlled by model transitions, never mass-assigned from input.
#[derive(
    Debug,
    Clone,
    Copy,
    PartialEq,
    Eq,
    EnumIter,
    DeriveActiveEnum,
    serde::Serialize,
    serde::Deserialize,
    utoipa::ToSchema,
)]
#[sea_orm(
    rs_type = "String",
    db_type = "String(StringLen::None)",
    rename_all = "snake_case"
)]
#[serde(rename_all = "snake_case")]
pub enum RequestStatus {
    Open,
    Assigned,
    Closed,
    Cancelled,
}

impl RequestStatus {
    pub fn label(self) -> &'static str {
        match self {
            Self::Open => "Open",
            Self::Assigned => "Assigned",
            Self::Closed => "Closed",
            Self::Cancelled => "Cancelled",
        }
    }
}

